import sys

def main():
    data = sys.stdin.buffer.read()
    sums = {}
    get = sums.get
    for line in data.split(b"\n")[1:]:
        p = line.split(b",")
        if len(p) < 3:
            continue
        try:
            v = float(p[2])
        except ValueError:
            continue
        c = p[1]
        sums[c] = get(c, 0.0) + v
    out = [c + b"," + ("%.2f" % sums[c]).encode() + b"\n" for c in sorted(sums)]
    sys.stdout.buffer.write(b"".join(out))

main()
